| fpu_sane_comp_unnorm.s -- MC68040 UNSUPPORTED DATA TYPE (vector 55) through the REAL
| Q700 ROM FPSP (x_unsupp, $4088DAB0), on the exact SANE sequence that made Speedometer
| 4.02's Benchmark Mix report "KWhetstones/sec 0.000".
|
| Requires CPU_FP_UNSUPP_TRAP=1 (see fpu_sane_comp_unnorm.requires). Without it the core
| computes on the unnormal operand and stage 1 fails with 0xDF00403E.
|
| Stage 1  ROM PACK4 comp->extended loader ($408EB710) verbatim: push {$403E,$403E} +
|          64-bit comp, `fmove.x (sp)+,fp1` -- an UNNORMALIZED extended source. A real
|          040 traps (vector 55); x_unsupp normalises it in software and RTEs past the
|          instruction. Then Speedometer's score: seconds = elapsed/1e6, KWhet =
|          1000/seconds with FODIV's `fmovem.x dst ; fdiv.x src`. elapsed = 100000 us ->
|          KWhet must be exactly 10000. Also: SP advanced by exactly 12 (the (An)+ EA
|          completes before the trap), exactly ONE vector-55 entry.
| Stage 2  `fmove.x (d16,a0),fp2` of an unnormal ($4000, mantissa 3) -> 3*2^-62
|          = {$3FC2, $C000000000000000}.
| Stage 3  `fmove.s (a0),fp3` of the single denormal $00000001 -> 2^-149 (STAG 101 path,
|          $4088E202) = {$3F6A, $8000000000000000}.
| Stage 4  `fmove.d (a0),fp3` of the double denormal 1 -> 2^-1074 = {$3BCD, $8000...}.
| Stage 5  `fmove.x fp4,fp5` with FP4 holding an unnormal (loaded by FMOVEM.X, which does
|          no data-type check) -- the FPREG source path -> 3*2^-62.
| Stage 6  `ftst.x fp4` (unnormal) -> trap, software sets FPCC = positive (FBGT taken).
|
| FAIL codes at 0xFFFF0000:
|   0xDF00eeee  stage-1 KWhet wrong (eeee = exponent word FMOVE.X produced)
|   0xBAD5000s  stage s: wrong value / SP / trap count
|   0xBAD00002/3/4/A/B  unexpected vector 2/3/4/10/11
    .text
    .org 0
    .equ PASS_SENT, 0xFFFF0000
    .equ SCR, 0x00020000
_start:
    lea     0x00011000, %a7
    move.l  #_h2,  0x08
    move.l  #_h3,  0x0C
    move.l  #_h4,  0x10
    move.l  #_h10, 0x28
    move.l  #_h11, 0x2C
    move.l  #_v55, 0xDC                 | vector 55 -> count, then the ROM FPSP
    moveq   #0, %d6
    | constants
    move.l  #0x40120000, SCR+0x40       | 1e6
    move.l  #0xF4240000, SCR+0x44
    clr.l   SCR+0x48
    move.l  #0x40080000, SCR+0x50       | 1000
    move.l  #0xFA000000, SCR+0x54
    clr.l   SCR+0x58

    | ── Stage 1 ──────────────────────────────────────────────────────
    move.l  %a7, %d7
    move.l  #100000, -(%sp)
    clr.l   -(%sp)
    move.l  #0x403E403E, -(%sp)
    fmove.x (%sp)+, %fp1
    cmp.l   %a7, %d7
    bne     _f1
    cmp.l   #1, %d6
    bne     _f1
    lea     SCR, %a0
    fmove.x %fp1, (%a0)
    move.w  (%a0), %d1
    fmovem.x (%a0), %fp0
    fdiv.x  SCR+0x40, %fp0
    fmove.x %fp0, SCR+0x20
    fmovem.x SCR+0x50, %fp2
    fdiv.x  SCR+0x20, %fp2
    fmove.l %fp2, %d3
    cmp.l   #10000, %d3
    bne     _fk
    cmp.l   #1, %d6                     | the divides are on normals: no more traps
    bne     _f1

    | ── Stage 2 ──────────────────────────────────────────────────────
    moveq   #0, %d6
    lea     SCR+0x100, %a0
    move.l  #0x40000000, 0x10(%a0)
    clr.l   0x14(%a0)
    move.l  #3, 0x18(%a0)
    fmove.x 0x10(%a0), %fp2
    lea     SCR+0x80, %a1
    fmove.x %fp2, (%a1)
    cmp.l   #0x3FC20000, (%a1)
    bne     _f2
    cmp.l   #0xC0000000, 4(%a1)
    bne     _f2
    tst.l   8(%a1)
    bne     _f2
    cmp.l   #1, %d6
    bne     _f2

    | ── Stage 3 ──────────────────────────────────────────────────────
    moveq   #0, %d6
    move.l  #1, (%a0)
    fmove.s (%a0), %fp3
    fmove.x %fp3, (%a1)
    cmp.l   #0x3F6A0000, (%a1)
    bne     _f3
    cmp.l   #0x80000000, 4(%a1)
    bne     _f3
    tst.l   8(%a1)
    bne     _f3
    cmp.l   #1, %d6
    bne     _f3

    | ── Stage 4 ──────────────────────────────────────────────────────
    moveq   #0, %d6
    clr.l   (%a0)
    move.l  #1, 4(%a0)
    fmove.d (%a0), %fp3
    fmove.x %fp3, (%a1)
    cmp.l   #0x3BCD0000, (%a1)
    bne     _f4
    cmp.l   #0x80000000, 4(%a1)
    bne     _f4
    tst.l   8(%a1)
    bne     _f4
    cmp.l   #1, %d6
    bne     _f4

    | ── Stage 5 ──────────────────────────────────────────────────────
    moveq   #0, %d6
    fmovem.x 0x10(%a0), %fp4            | unnormal into FP4, no check
    cmp.l   #0, %d6
    bne     _f5
    fmove.x %fp4, %fp5
    fmove.x %fp5, (%a1)
    cmp.l   #0x3FC20000, (%a1)
    bne     _f5
    cmp.l   #0xC0000000, 4(%a1)
    bne     _f5
    cmp.l   #1, %d6
    bne     _f5

    | ── Stage 6 ──────────────────────────────────────────────────────
    moveq   #0, %d6
    fmove.l #0, %fpsr
    ftst.x  %fp4
    fbngt   _f6
    cmp.l   #1, %d6
    bne     _f6

    move.l  #0xC0FFEE00, PASS_SENT
_halt:
    bra     _halt

_fk:
    andi.l  #0xFFFF, %d1
    ori.l   #0xDF000000, %d1
    move.l  %d1, PASS_SENT
    bra     _halt
_f1: move.l #0xBAD50001, PASS_SENT
    bra     _halt
_f2: move.l #0xBAD50002, PASS_SENT
    bra     _halt
_f3: move.l #0xBAD50003, PASS_SENT
    bra     _halt
_f4: move.l #0xBAD50004, PASS_SENT
    bra     _halt
_f5: move.l #0xBAD50005, PASS_SENT
    bra     _halt
_f6: move.l #0xBAD50006, PASS_SENT
    bra     _halt
_v55:
    addq.l  #1, %d6
    jmp     0x4088DAB0
_h2: move.l #0xBAD00002, PASS_SENT
    bra     _halt
_h3: move.l #0xBAD00003, PASS_SENT
    bra     _halt
_h4: move.l #0xBAD00004, PASS_SENT
    bra     _halt
_h10: move.l #0xBAD0000A, PASS_SENT
    bra     _halt
_h11: move.l #0xBAD0000B, PASS_SENT
    bra     _halt

